# Construct the vertical stack of carved 5x5 tiles, cropped with a one-cell border.
out = [[1]*7 for _ in range(19)]
blocks = [(1,3,[[1,0,1],[1,0,1],[1,1,1]]),
          (7,9,[[0,0,1],[0,1,1],[1,0,1]]),
          (13,8,[[1,1,1],[0,1,0],[1,1,1]])]
for r0,color,mask in blocks:
    for r in range(r0,r0+5):
        for c in range(1,6):
            out[r][c]=color
    for dr,row in enumerate(mask):
        for dc,marked in enumerate(row):
            if marked:
                out[r0+1+dr][2+dc]=1
print('\n'.join(' '.join(map(str,row)) for row in out))
